
CREATE TABLE public.ogretim_modelleri (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ad text NOT NULL, asamalar jsonb NOT NULL DEFAULT '[]'::jsonb, denetim_kurallari jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.kazanimlar (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kod text NOT NULL, metin text NOT NULL, atolye_alani text NOT NULL, yas_grubu text NOT NULL, bloom_seviyesi text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.planlar (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kazanim_id uuid REFERENCES public.kazanimlar(id) ON DELETE SET NULL, model_id uuid REFERENCES public.ogretim_modelleri(id) ON DELETE SET NULL, yas_grubu text NOT NULL, toplam_sure integer NOT NULL DEFAULT 90, ogrenci_sayisi integer NOT NULL DEFAULT 20, butce numeric NOT NULL DEFAULT 0, durum text NOT NULL DEFAULT 'taslak', versiyon integer NOT NULL DEFAULT 1, icerik jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.denetim_bulgulari (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES public.planlar(id) ON DELETE CASCADE, kural_no integer NOT NULL, seviye text NOT NULL, gecti boolean NOT NULL DEFAULT false, mesaj text, kanit_alintisi text, ilgili_asama text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.geri_bildirimler (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES public.planlar(id) ON DELETE CASCADE, uygulandi_mi boolean NOT NULL DEFAULT false, not_metni text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.surumler (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES public.planlar(id) ON DELETE CASCADE, versiyon_no integer NOT NULL, snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());

GRANT SELECT, INSERT, UPDATE, DELETE ON public.ogretim_modelleri, public.kazanimlar, public.planlar, public.denetim_bulgulari, public.geri_bildirimler, public.surumler TO anon, authenticated;
GRANT ALL ON public.ogretim_modelleri, public.kazanimlar, public.planlar, public.denetim_bulgulari, public.geri_bildirimler, public.surumler TO service_role;

ALTER TABLE public.ogretim_modelleri ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kazanimlar ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.planlar ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.denetim_bulgulari ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.geri_bildirimler ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.surumler ENABLE ROW LEVEL SECURITY;

CREATE POLICY "acik_erisim" ON public.ogretim_modelleri FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "acik_erisim" ON public.kazanimlar FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "acik_erisim" ON public.planlar FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "acik_erisim" ON public.denetim_bulgulari FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "acik_erisim" ON public.geri_bildirimler FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "acik_erisim" ON public.surumler FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

INSERT INTO public.ogretim_modelleri (ad, asamalar, denetim_kurallari) VALUES ('5E', '[{"ad": "Girme", "oran": 0.11, "amac": "Ön bilgiyi yüzeye çıkarmak, merak ve zihinsel çatışma yaratmak"}, {"ad": "Keşfetme", "oran": 0.33, "amac": "Öğrencinin elleriyle deneyimlemesi, veri toplaması"}, {"ad": "Açıklama", "oran": 0.22, "amac": "Önce öğrenci kendi bulgusunu anlatır, sonra öğretmen terminolojiyi verir"}, {"ad": "Derinleştirme", "oran": 0.22, "amac": "Kavramı yeni bir bağlama aktarmak"}, {"ad": "Değerlendirme", "oran": 0.11, "amac": "Kazanıma ulaşılıp ulaşılmadığını ölçmek"}]'::jsonb, '[{"no": 1, "seviye": "kritik", "aciklama": "Açıklama aşaması öğrenci bulgusundan önce terminoloji vermemeli"}, {"no": 2, "seviye": "kritik", "aciklama": "Her aşama kazanımla açıkça ilişkili olmalı"}, {"no": 3, "seviye": "uyari", "aciklama": "Keşfetme aşaması toplam sürenin en az %30''u olmalı"}, {"no": 4, "seviye": "uyari", "aciklama": "Malzeme toplam maliyeti bütçe üst sınırını aşmamalı"}, {"no": 5, "seviye": "bilgi", "aciklama": "Her etkinlikte farklılaştırma (destek/zenginleştirme) bulunmalı"}]'::jsonb);

