('EL-01','Elektronik ve IoT','9-11','Kavrama','Kapalı devre ile açık devre arasındaki farkı basit bir devre kurarak açıklar'),
('EL-02','Elektronik ve IoT','12-14','Uygulama','Bir sensörden gelen veriyi okuyup eşik değere göre çıktı üretir'),
('EL-03','Elektronik ve IoT','15-17','Sentez','Belirlenen bir ihtiyaca yönelik sensör-aktüatör sistemi tasarlar'),
('YZ-01','Yapay Zekâ ve Veri','12-14','Kavrama','Etiketli veri ile sınıflandırma kavramını günlük hayat örneğiyle açıklar'),
('YZ-02','Yapay Zekâ ve Veri','15-17','Analiz','Bir veri kümesindeki yanlılığın model çıktısını nasıl etkilediğini inceler'),
('TU-01','Tasarım ve Üretim','9-11','Uygulama','Verilen kısıtlar altında basit bir taşıyıcı yapı tasarlar ve test eder'),
('TU-02','Tasarım ve Üretim','12-14','Analiz','Bir tasarımın başarısızlık noktasını test verisiyle belirler ve iyileştirir'),
('EN-01','Enerji Teknolojileri','12-14','Kavrama','Enerji dönüşümünü bir düzenek üzerinde gözlemleyerek açıklar'),
('EN-02','Enerji Teknolojileri','15-17','Değerlendirme','İki farklı enerji kaynağını verim ve maliyet açısından karşılaştırır');

INSERT INTO public.planlar (kazanim_id, model_id, yas_grubu, toplam_sure, ogrenci_sayisi, butce, durum, versiyon, icerik)
SELECT k.id, m.id, '12-14', 90, 20, 2500, 'taslak', 1, '{"baslik": "Sensörle Karar Veren Sistemler: Eşik Değeri Keşfediyoruz", "ozet": "Öğrenciler ışık sensöründen gelen veriyi okuyup bir eşik değere göre LED çıkışı üretir.", "asamalar": [{"ad": "Girme", "sure": 10, "amac": "Otomatik sokak lambalarının nasıl karar verdiğini sorgulatmak", "ogretmen_eylemi": "Karanlıkta yanan sokak lambası videosu gösterir, ''lamba nereden biliyor?'' sorusunu sorar.", "ogrenci_eylemi": "Tahminlerini yazar ve sınıfla paylaşır.", "tetikleyici_sorular": ["Lamba karanlığı nasıl anlıyor?", "Işık miktarı bir sayıyla ifade edilebilir mi?"], "kavram_yanilgilari": ["Sensör ''görür'' ve karar verir", "Sensör açık/kapalı iki değer üretir"]}, {"ad": "Keşfetme", "sure": 30, "amac": "LDR verisini ölçüp kaydetmek", "ogretmen_eylemi": "Devre şemasını dağıtır, ölçüm tablosunu tanıtır, gruplara rehberlik eder.", "ogrenci_eylemi": "LDR devresini kurar, farklı ışık koşullarında değer okuyup tabloya kaydeder.", "tetikleyici_sorular": ["El ile kapatınca değer nasıl değişti?", "Hangi değerden sonra ''karanlık'' diyebiliriz?"], "kavram_yanilgilari": ["Ölçüm değeri her ortamda aynıdır", "Kablo sırası önemsizdir"]}, {"ad": "Açıklama", "sure": 20, "amac": "Eşik değer kavramını öğrenci verisinden yola çıkarak adlandırmak", "ogretmen_eylemi": "Grup verilerini tahtada toplar; ardından ''eşik değer'' ve ''analog okuma'' terimlerini tanıtır.", "ogrenci_eylemi": "Kendi tablosundaki geçiş noktasını sunar.", "tetikleyici_sorular": ["Grupların eşik değerleri neden farklı çıktı?"], "kavram_yanilgilari": ["Eşik değer evrensel bir sabittir"]}, {"ad": "Derinleştirme", "sure": 20, "amac": "Kavramı yeni bağlama aktarmak", "ogretmen_eylemi": "Sera nem sensörü senaryosunu verir.", "ogrenci_eylemi": "Nem eşiğine göre sulama yapan sözde kodu yazar.", "tetikleyici_sorular": ["Eşiği yanlış seçersek ne olur?"], "kavram_yanilgilari": ["Her sensör aynı aralıkta değer üretir"]}, {"ad": "Değerlendirme", "sure": 10, "amac": "Kazanıma ulaşımı ölçmek", "ogretmen_eylemi": "Çıkış kartını dağıtır ve kısa performans görevini açıklar.", "ogrenci_eylemi": "Kendi eşik değerini gerekçesiyle yazar.", "tetikleyici_sorular": ["Eşik değerini neden bu sayı seçtin?"], "kavram_yanilgilari": ["Doğru tek bir eşik vardır"]}], "etkinlikler": [{"tip": "deney", "ad": "Işık Haritası", "asama": "Keşfetme", "sure": 20, "adimlar": ["LDR ve 10k direnci gerilim bölücü olarak bağla", "Kartı bilgisayara bağla ve seri ekranı aç", "Aydınlık, gölge ve kapalı durumda üçer ölçüm al", "Değerleri tabloya yaz"], "kazanim_hizasi": "EL-02 — sensör verisini okuma", "farklilastirma": {"destek": "Hazır bağlanmış devre ve ölçüm şablonu verilir", "zenginlestirme": "Ölçümlerin ortalaması ve sapması hesaplanır"}}, {"tip": "kart-kutu oyunu", "ad": "Eşik Kartları", "asama": "Açıklama", "sure": 10, "adimlar": ["Gruplara sensör değeri kartları dağıtılır", "Her grup kartı ''aç'' veya ''kapat'' kutusuna atar", "Sınır kartlarda tartışma açılır"], "kazanim_hizasi": "EL-02 — eşik değer kavramı", "farklilastirma": {"destek": "Kartlarda renk ipucu bulunur", "zenginlestirme": "Grup kendi kart setini üretir"}}, {"tip": "oyunlaştırma", "ad": "Sera Görevi", "asama": "Derinleştirme", "sure": 15, "adimlar": ["Her gruba farklı bitki senaryosu verilir", "Nem eşiği belirlenir", "Sözde kod panoya yazılır", "Diğer gruplar puanlar"], "kazanim_hizasi": "EL-02 — eşik ile çıktı üretme", "farklilastirma": {"destek": "Sözde kod şablonu verilir", "zenginlestirme": "İki sensörlü koşul kurgulanır"}}], "malzemeler": [{"ad": "LDR sensör", "adet": 10, "birim_maliyet": 8, "hazirlik_suresi": 5, "guvenlik_notu": "Yok", "alternatif": "Fotodiyot"}, {"ad": "10k direnç", "adet": 10, "birim_maliyet": 1, "hazirlik_suresi": 5, "guvenlik_notu": "Yok", "alternatif": "4.7k direnç"}, {"ad": "Mikrodenetleyici kartı", "adet": 5, "birim_maliyet": 220, "hazirlik_suresi": 15, "guvenlik_notu": "USB bağlantısını ıslak elle takmayın", "alternatif": "Okul setindeki kart"}, {"ad": "Breadboard", "adet": 5, "birim_maliyet": 45, "hazirlik_suresi": 5, "guvenlik_notu": "Yok", "alternatif": "Lehimsiz devre kiti"}, {"ad": "LED ve jumper kablo seti", "adet": 5, "birim_maliyet": 35, "hazirlik_suresi": 10, "guvenlik_notu": "Kısa devreden kaçının", "alternatif": "Mevcut envanter"}], "medya": [{"tip": "video", "aciklama": "Alacakaranlıkta yanan sokak lambaları", "arama_terimi": "street light photocell dusk", "asama": "Girme"}, {"tip": "görsel", "aciklama": "Gerilim bölücü devre şeması", "arama_terimi": "LDR voltage divider schematic", "asama": "Keşfetme"}, {"tip": "animasyon", "aciklama": "Eşik değer karşılaştırma animasyonu", "arama_terimi": "threshold comparison animation", "asama": "Açıklama"}, {"tip": "simülasyon", "aciklama": "Çevrimiçi devre simülatörü", "arama_terimi": "online circuit simulator LDR", "asama": "Derinleştirme"}], "olcme": {"bicimlendirici_sorular": ["Sensör değeri arttığında ortam aydınlanıyor mu, kararıyor mu?", "Eşik değeri değiştirirsen sistem nasıl davranır?", "Ölçümlerin neden gruplar arasında farklı?"], "performans_gorevi": "Sınıfın ışık koşullarına uygun bir eşik değer belirleyip, bu değere göre LED yakan sistemi kurar ve seçimini veriyle gerekçelendirir.", "rubrik": [{"kriter": "Veri toplama", "puan3": "Üç koşulda da tutarlı ölçüm alır ve kaydeder", "puan2": "Ölçüm alır, kaydı eksiktir", "puan1": "Ölçüm alamaz"}, {"kriter": "Eşik belirleme", "puan3": "Eşiği veriye dayandırarak gerekçelendirir", "puan2": "Eşik belirler, gerekçesi zayıftır", "puan1": "Rastgele eşik seçer"}, {"kriter": "Sistem kurulumu", "puan3": "Devre ve kod hatasız çalışır", "puan2": "Küçük destekle çalışır", "puan1": "Çalışmaz"}]}}'::jsonb
FROM public.kazanimlar k, public.ogretim_modelleri m WHERE k.kod='EL-02' AND m.ad='5E';
